/// <summary>
/// 三叉喷射状态（结核分枝杆菌等）— 进入攻击范围后沿三个固定角喷射：
/// 1) 进入状态即尝试释放三叉喷射技能（方向固定，不随玩家位置变化）；
/// 2) 喷射期间锁定移动（前摇 + 喷射全程原地不动，由 TriSprayRuntime 禁用 EnemyMovement）；
/// 3) 喷射结束后切回 ChaseState；技能冷却中则原地待命等待冷却。
/// </summary>
public class AxialSprayState : EnemyStateBase
{
    /// <summary>是否已触发喷射（进入喷射锁定阶段）</summary>
    private bool _spraying;

    public AxialSprayState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        Core.Movement?.Stop();
        _spraying = false;
    }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.Health == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        // ── 喷射锁定阶段：前摇 + 喷射全程原地不动 ──
        if (_spraying)
        {
            Core.Movement?.Stop();

            // 检测喷射是否结束（TriSprayRuntime 结束时会恢复 EnemyMovement）
            var runtime = Object.FindObjectOfType<TriSprayRuntime>();
            if (runtime == null || !runtime.IsActive)
            {
                Core.StateMachine.ChangeState(new ChaseState(Core));
            }
            return;
        }

        // ── 未喷射：尝试释放三叉喷射（方向固定，不依赖玩家位置） ──
        if (Core.SkillManager != null && Core.SkillManager.TryCastSkill(0, Core, Core.GetTargetDirection()))
        {
            _spraying = true;
        }
        // 技能冷却中则原地待命（保持不动，等待冷却）
        else
        {
            Core.Movement?.Stop();
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Boss 核心 — 挂在有 EnemyCore 的 GameObject 上，管理阶段切换和技能调度。
/// 使用 EnemySkillManager 管理技能，不自行维护技能列表。
/// skillLibrary 取自 EnemyConfig.skillLibrary。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class BossCore : MonoBehaviour
{
    [Header("阶段配置")]
    [Tooltip("按健康阈值升序排列的阶段 (Phase1 在前, Phase2 在后)")]
    [SerializeField] private BossPhaseData[] _phases;

    [Header("调试")]
    [SerializeField] private int _currentPhaseIndex;
    [SerializeField] private float _nextSkillTime;

    private EnemyCore _enemyCore;
    private EnemyStats _health;
    private EnemyMovement _movement;
    private EnemySkillManager _skillManager;
    private SkillLibrary _skillLibrary;
    private BossPhaseData CurrentPhase => _phases != null && _currentPhaseIndex < _phases.Length
        ? _phases[_currentPhaseIndex] : null;

    private void Awake()
    {
        _enemyCore = GetComponent<EnemyCore>();
        _health = GetComponent<EnemyStats>();
        _movement = GetComponent<EnemyMovement>();
        _skillManager = GetComponent<EnemySkillManager>();

        if (_phases == null || _phases.Length == 0)
        {
            Debug.LogWarning("BossCore: 未配置 _phases，Boss 将无法切换阶段");
            return;
        }
    }

    private void Start()
    {
        _skillLibrary = _enemyCore.config != null ? _enemyCore.config.skillLibrary : null;
        if (_skillLibrary == null)
            Debug.LogWarning("BossCore: EnemyConfig.skillLibrary 未配置");

        LoadPhaseSkills(0);
    }

    private void OnEnable()
    {
        if (_health != null)
            _health.OnHealthChanged += OnHealthChanged;
    }

    private void OnDisable()
    {
        if (_health != null)
            _health.OnHealthChanged -= OnHealthChanged;
    }

    private void Update()
    {
        if (_enemyCore.IsDead) return;

        float dt = Time.deltaTime;

        // Tick skill cooldowns via EnemySkillManager
        if (_skillManager != null)
            _skillManager.TickCooldowns(dt);

        TryCastSkill();
    }

    // ==================== 阶段切换 ====================

    private void OnHealthChanged(float currentHp, float maxHp)
    {
        float ratio = maxHp > 0 ? currentHp / maxHp : 1f;

        for (int i = _phases.Length - 1; i > _currentPhaseIndex; i--)
        {
            if (ratio <= _phases[i].healthThreshold)
            {
                EnterPhase(i);
                return;
            }
        }
    }

    private void EnterPhase(int phaseIndex)
    {
        _currentPhaseIndex = phaseIndex;
        var newPhase = CurrentPhase;
        if (newPhase == null) return;

        Debug.Log($"BossCore: 进入 {newPhase.phaseName}");

        LoadPhaseSkills(phaseIndex);

        if (_health != null)
        {
            float baseSpeed = _health.ChaseSpeed;
            _health.ChaseSpeed = baseSpeed * newPhase.moveSpeedMult;
        }

        _nextSkillTime = Time.time + 0.5f;
    }

    // ==================== 技能管理（通过 EnemySkillManager） ====================

    private void LoadPhaseSkills(int phaseIndex)
    {
        if (_phases == null || phaseIndex >= _phases.Length || _skillManager == null || _skillLibrary == null) return;
        var phase = _phases[phaseIndex];
        if (phase.skills == null) return;

        var ids = new List<string>();
        foreach (var sd in phase.skills)
            if (sd != null) ids.Add(sd.skillId);

        _skillManager.LoadSkills(_skillLibrary, ids.ToArray());
    }

    private void TryCastSkill()
    {
        var phase = CurrentPhase;
        if (phase == null || _skillManager == null) return;
        if (Time.time < _nextSkillTime) return;

        var ready = _skillManager.GetReadySkill();
        if (ready == null) return;

        Vector2 dir = _enemyCore.PlayerTarget != null
            ? (_enemyCore.PlayerTarget.position - transform.position).normalized
            : Vector2.down;

        ready.TryCast(_enemyCore, dir);
        _nextSkillTime = Time.time + phase.skillInterval;
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 动情腺溢散 buff 效果 — 混淆房间内敌人的攻击目标，使其互相攻击。
/// OnApply — 收集房间所有存活敌人，把每个敌人的 PlayerTarget 设为其相邻敌人
///           （A→B→C→…→A 循环链），敌人会去追击并攻击彼此。
/// OnRemove — 恢复所有敌人的 PlayerTarget 指向玩家。
/// 泛用"混乱/自相残杀"类 debuff：可作为范围混乱技能的效果策略复用。
/// </summary>
[CreateAssetMenu(fileName = "ConfusionBuff", menuName = "Game/Buff Effect/Gland Confusion")]
public class ConfusionBuff : BuffEffectBase
{
    /// <summary>记录被混乱的敌人及其原目标（用于恢复）</summary>
    private static readonly Dictionary<BuffInstance, List<EnemyConfusionRecord>> _records
        = new Dictionary<BuffInstance, List<EnemyConfusionRecord>>();

    private class EnemyConfusionRecord
    {
        public EnemyCore enemy;
        public Transform originalTarget;
    }

    public override void OnApply(GameObject target, BuffInstance buff)
    {
        // 收集房间所有存活敌人（排除死亡/同化/Boss）
        var enemies = Object.FindObjectsOfType<EnemyCore>();
        var candidates = new List<EnemyCore>();
        foreach (var e in enemies)
        {
            if (e == null || e.IsDead || e.IsAssimilated) continue;
            if (e.GetComponent<BossCore>() != null) continue;
            candidates.Add(e);
        }

        if (candidates.Count < 2)
        {
            Debug.Log("[GlandConfusion] 敌人不足 2 个，无法混淆");
            return;
        }

        var records = new List<EnemyConfusionRecord>();

        // 构建循环链：A→B→C→…→A（每个敌人的目标是下一个敌人）
        for (int i = 0; i < candidates.Count; i++)
        {
            var enemy = candidates[i];
            var next = candidates[(i + 1) % candidates.Count];

            var record = new EnemyConfusionRecord
            {
                enemy = enemy,
                originalTarget = enemy.PlayerTarget
            };

            // 设置互为目标（下一个敌人）
            enemy.PlayerTarget = next.transform;

            records.Add(record);
        }

        _records[buff] = records;
        Debug.Log($"[GlandConfusion] 混淆 {records.Count} 个敌人互相攻击");
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        if (!_records.TryGetValue(buff, out var records)) return;

        // 恢复所有敌人目标指向玩家
        var player = GameObject.FindGameObjectWithTag("Player");
        foreach (var record in records)
        {
            if (record.enemy == null) continue;
            record.enemy.PlayerTarget = player != null ? player.transform : record.originalTarget;
        }

        _records.Remove(buff);
        Debug.Log("[GlandConfusion] 敌人目标已恢复");
    }
}

using UnityEngine;

/// <summary>
/// 急性谵妄 buff 效果：敌人不再以玩家为目标，随处乱走，不发射弹幕。
/// OnApply — 清除玩家目标、切换 ConfusedState（乱走）、禁用技能管理器；
/// OnRemove — 恢复技能管理器、重新定位玩家、切回 Idle/Patrol。
/// 泛用减益效果：可作为"混乱/迷惑/失智"类 debuff 的效果策略复用。
/// </summary>
[CreateAssetMenu(fileName = "DeliriumBuff", menuName = "Game/Buff Effect/Delirium (Confusion)")]
public class DeliriumBuff : BuffEffectBase
{
    public override void OnApply(GameObject target, BuffInstance buff)
    {
        var core = target.GetComponent<EnemyCore>();
        if (core == null || core.IsDead) return;

        // 已同化的随从不受影响（是自己人）
        if (core.IsAssimilated) return;

        // 不再以玩家为目标
        core.PlayerTarget = null;

        // 禁用技能（不发射弹幕）
        if (core.SkillManager != null)
            core.SkillManager.enabled = false;

        // 停止当前行为，切换到乱走状态
        if (core.StateMachine != null)
            core.StateMachine.ChangeState(new ConfusedState(core));
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        var core = target.GetComponent<EnemyCore>();
        if (core == null || core.IsDead) return;

        // 恢复技能
        if (core.SkillManager != null)
            core.SkillManager.enabled = true;

        // 重新定位玩家
        if (core.PlayerTarget == null)
        {
            var player = GameObject.FindGameObjectWithTag("Player");
            if (player != null) core.PlayerTarget = player.transform;
        }

        // 恢复正常 AI（有巡逻点则巡逻，否则空闲）
        if (core.StateMachine != null)
        {
            if (core.config != null && core.config.patrolPoints != null && core.config.patrolPoints.Count > 0)
                core.StateMachine.ChangeState(new PatrolState(core));
            else
                core.StateMachine.ChangeState(new IdleState(core));
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 消耗血量召唤 buff 效果 — 周期性消耗自身血量并召唤随从。
/// 血量越低，召唤间隔越短（召唤越快）。
/// 召唤逻辑复用 SummonSkillEffect 的预制体池 + 阵营标记。
/// 泛用类：消耗量、基础间隔、召唤数量、预制体池均可配置。
/// 右键 -> Create -> Game -> Buff Effect -> Blood Cost Summon
/// </summary>
[CreateAssetMenu(fileName = "BloodCostSummonBuff", menuName = "Game/Buff Effect/Blood Cost Summon")]
public class BloodCostSummonBuff : BuffEffectBase
{
    [Header("血量消耗")]
    [Tooltip("每次召唤消耗的自身血量")]
    public float healthCost = 5f;

    [Header("召唤配置")]
    [Tooltip("敌方阵营召唤的随从预制体池")]
    public GameObject[] enemyMinionPrefabs;
    [Tooltip("友方阵营召唤的随从预制体池")]
    public GameObject[] playerMinionPrefabs;
    [Tooltip("每次召唤数量")]
    public int count = 3;
    [Tooltip("召唤散布半径")]
    public float spawnRadius = 2f;

    [Header("召唤节奏")]
    [Tooltip("血量满时的召唤间隔（秒）")]
    public float maxInterval = 6f;
    [Tooltip("血量最低时的召唤间隔（秒）")]
    public float minInterval = 2f;

    private static readonly Dictionary<BuffInstance, float> _timers = new Dictionary<BuffInstance, float>();

    public override void OnApply(GameObject target, BuffInstance buff)
    {
        _timers[buff] = 0f;
    }

    public override void OnTick(GameObject target, BuffInstance buff, float deltaTime)
    {
        if (!_timers.TryGetValue(buff, out float timer))
        {
            timer = 0f;
            _timers[buff] = timer;
        }

        // 根据当前血量百分比计算召唤间隔（血量越低越快）
        float currentInterval = GetCurrentInterval(target);

        timer += deltaTime;
        if (timer < currentInterval)
        {
            _timers[buff] = timer;
            return;
        }

        _timers[buff] = 0f;

        // 消耗自身血量
        var damageable = target.GetComponent<IDamageable>();
        if (damageable != null)
            damageable.TakeDamage(healthCost);

        // 召唤随从
        SummonMinions(target);
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        _timers.Remove(buff);
    }

    private float GetCurrentInterval(GameObject target)
    {
        // 尝试读取血量百分比
        float hpPercent = 1f;
        var stats = target.GetComponent<EnemyStats>();
        if (stats != null && stats.MaxHealth > 0f)
            hpPercent = stats.CurrentHealth / stats.MaxHealth;
        else
        {
            var playerStats = target.GetComponent<PlayerStats>();
            if (playerStats != null && playerStats.MaxHealth > 0f)
                hpPercent = playerStats.CurrentHealth / playerStats.MaxHealth;
        }

        // hpPercent=1 → maxInterval, hpPercent=0 → minInterval
        return Mathf.Lerp(minInterval, maxInterval, hpPercent);
    }

    private void SummonMinions(GameObject caster)
    {
        bool isPlayerSide = caster.CompareTag("Player");
        var pool = isPlayerSide ? playerMinionPrefabs : enemyMinionPrefabs;
        if (pool == null || pool.Length == 0) return;

        string selfTag = isPlayerSide ? "Player" : "Enemy";
        Vector2 center = caster.transform.position;
        Transform parent = caster.transform.parent;

        // 找到所属房间（门锁由 RoomManager._aliveEnemies 控制）+ 生成器（计数）
        var room = parent != null ? parent.GetComponentInParent<RoomManager>() : null;
        var spawner = parent != null ? parent.GetComponentInParent<EnemySpawner>() : null;

        for (int i = 0; i < count; i++)
        {
            var prefab = pool[Random.Range(0, pool.Length)];
            if (prefab == null) continue;

            Vector2 offset = Random.insideUnitCircle * spawnRadius;
            var go = Object.Instantiate(prefab, center + offset, Quaternion.identity, parent);
            go.name = $"Summon_{prefab.name}_{i}";
            go.tag = selfTag;

            // 设置初始目标
            var core = go.GetComponent<EnemyCore>();
            if (core != null)
            {
                // 找最近敌方
                string targetTag = isPlayerSide ? "Enemy" : "Player";
                var targets = GameObject.FindGameObjectsWithTag(targetTag);
                if (targets.Length > 0)
                {
                    Transform best = null;
                    float bestDist = float.MaxValue;
                    foreach (var t in targets)
                    {
                        float d = Vector2.SqrMagnitude((Vector2)t.transform.position - center);
                        if (d < bestDist) { bestDist = d; best = t.transform; }
                    }
                    if (best != null) core.PlayerTarget = best;
                }
            }

            // 计入房间敌人计数，避免房间门提前开启
            if (!isPlayerSide)
            {
                room?.RegisterEnemy(go);
                spawner?.RegisterEnemy(go);
            }
        }

        Debug.Log($"[BloodCostSummon] {caster.name} 消耗 {healthCost} 血 → 召唤 {count} 个随从");
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 召唤技能：在施法者周围随机位置生成单位。
/// 根据施法者阵营自动选择预制体池、Tag 与目标。
/// </summary>
[CreateAssetMenu(fileName = "SummonEffect", menuName = "Game/Skill Effect/Summon")]
public class SummonSkillEffect : SkillEffectBase
{
    [Header("召唤 — 敌方单位池（Boss/Enemy 释放时使用）")]
    [Tooltip("生成的单位 Tag=Enemy，攻击玩家")]
    public GameObject[] enemyMinionPrefabs;

    [Header("召唤 — 友方单位池（Player 释放时使用）")]
    [Tooltip("生成的单位 Tag=Player，攻击敌人")]
    public GameObject[] playerMinionPrefabs;

    [Header("参数")]
    [Tooltip("召唤数量")]
    public int count = 3;

    [Tooltip("生成半径 (围绕施法者)")]
    public float spawnRadius = 4f;

    [Tooltip("生成间隔 (秒)")]
    public float spawnInterval = 0.3f;

    [Header("敌方优先生成（可选）")]
    [Tooltip("生成位置极高概率落在敌方单位坐标（如光子光柱）")]
    public bool preferEnemySpawn = false;
    [Tooltip("落在敌方坐标的概率（0~1，默认 0.9）")]
    [Range(0f, 1f)] public float enemySpawnChance = 0.9f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono == null) return;
        mono.StartCoroutine(SummonRoutine(caster, ownerType));
    }

    private System.Collections.IEnumerator SummonRoutine(ISkillCaster caster, Projectile.OwnerType ownerType)
    {
        GameObject[] pool = ownerType == Projectile.OwnerType.Player
            ? playerMinionPrefabs
            : enemyMinionPrefabs;

        if (pool == null || pool.Length == 0)
        {
            Debug.LogWarning("SummonSkillEffect: 无可用预制体池");
            yield break;
        }

        string targetTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        string selfTag   = ownerType == Projectile.OwnerType.Player ? "Player" : "Enemy";

        Vector2 center = caster.CasterTransform.position;
        Transform parent = caster.CasterTransform.parent;

        for (int i = 0; i < count; i++)
        {
            // 生成位置：高优先级判定 → 极高概率在敌方单位坐标
            Vector2 spawnPos;
            if (preferEnemySpawn && Random.value < enemySpawnChance)
            {
                var enemyPos = PickRandomEnemyPosition(targetTag);
                spawnPos = enemyPos.HasValue
                    ? enemyPos.Value
                    : center + Random.insideUnitCircle * spawnRadius;   // 无敌方 → 随机
            }
            else
            {
                spawnPos = center + Random.insideUnitCircle * spawnRadius;
            }

            GameObject prefab = pool[Random.Range(0, pool.Length)];
            if (prefab == null) continue;

            var go = Object.Instantiate(prefab, spawnPos, Quaternion.identity, parent);
            go.name = $"Summon_{ownerType}_{i}_{prefab.name}";

            // 阵营标记
            go.tag = selfTag;

            // 光子光柱：初始化伤害参数
            var beam = go.GetComponent<PhotonBeam>();
            if (beam != null)
                beam.Initialize(ownerType, caster.GetAttackStrength());

            // 设置敌人 Core 的初始目标
            var core = go.GetComponent<EnemyCore>();
            if (core != null)
            {
                var target = FindNearestTarget(spawnPos, targetTag);
                if (target != null)
                    core.PlayerTarget = target; // 字段名是 PlayerTarget，但实际是"攻击目标"
            }

            yield return new WaitForSeconds(spawnInterval);
        }
    }

    /// <summary>随机选一个敌方单位坐标（高优先级生成点），无敌方返回 null</summary>
    private static Vector2? PickRandomEnemyPosition(string targetTag)
    {
        var gos = GameObject.FindGameObjectsWithTag(targetTag);
        if (gos == null || gos.Length == 0)
            return null;

        var go = gos[Random.Range(0, gos.Length)];
        return (Vector2)go.transform.position;
    }

    private static Transform FindNearestTarget(Vector2 origin, string targetTag)
    {
        var gos = GameObject.FindGameObjectsWithTag(targetTag);
        if (gos == null || gos.Length == 0) return null;

        Transform best = null;
        float bestDist = float.MaxValue;
        foreach (var go in gos)
        {
            float d = Vector2.SqrMagnitude((Vector2)go.transform.position - origin);
            if (d < bestDist)
            {
                bestDist = d;
                best = go.transform;
            }
        }
        return best;
    }
}

