{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 2f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 12f;

    [Header("复活")]
    [Tooltip("死亡后复活延迟（秒）")]
    [SerializeField] private float _respawnDelay = 10f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private EnemySkillManager _skillManager;
    private bool _isActive;
    private bool _isReviving;

    // 进化倾向 buff：记录原始属性，动态刷新时从原始值重算
    private float _origMaxHealth, _origPatrolSpeed, _origChaseSpeed;
    private float _origDetectionRange, _origAttackRange, _origContactDamage, _origContactDamageCooldown;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    // ── 道具增强（静态，影响所有随从）──
    /// <summary>随从生命上限乘区（免疫球蛋白）</summary>
    public static float MaxHealthMultiplier = 1f;
    /// <summary>随从伤害乘区（集落刺激因子 CSF）</summary>
    public static float DamageMultiplier = 1f;
    /// <summary>随从技能冷却乘区（白细胞介素-2 IL-2）</summary>
    public static float FollowerCooldownFactor = 1f;
    /// <summary>随从攻击是否附带减速（干扰素）</summary>
    public static bool ApplySlow = false;
    /// <summary>减速比例（干扰素），0.8 = 减速20%</summary>
    public static float SlowFactor = 0.8f;
    /// <summary>减速持续时间（秒）</summary>
    public static float SlowDuration = 2f;
    /// <summary>随从数量上限（胸腺肽），默认4</summary>
    public static int MaxFollowerCount = 4;

    private void OnEnable()
    {
        ActiveFollowers.Add(this);

        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
        SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _skillManager = _core.SkillManager;

        // 记录原始属性，用于进化倾向 buff 重算
        if (_core.Health != null)
        {
            _origMaxHealth = _core.Health.MaxHealth;
            _origPatrolSpeed = _core.Health.PatrolSpeed;
            _origChaseSpeed = _core.Health.ChaseSpeed;
            _origDetectionRange = _core.Health.DetectionRange;
            _origAttackRange = _core.Health.AttackRange;
            _origContactDamage = _core.Health.ContactDamage;
            _origContactDamageCooldown = _core.Health.ContactDamageCooldown;

            // 应用当前进化倾向 buff
            ApplyEvolutionBuff();

            _core.Health.OnDied += HandleDeath;
        }

        // 先脱离房间父节点，再标记 DontDestroyOnLoad（对有父节点的子对象直接调用不生效）
        transform.SetParent(null);
        DontDestroyOnLoad(gameObject);
    }

    /// <summary>根据玩家进化倾向刷新随从全属性增幅（叠加道具乘区）</summary>
    public void ApplyEvolutionBuff()
    {
        if (_core?.Health == null || !_isActive) return;

        var playerStats = _player?.GetComponent<PlayerStats>();
        if (playerStats == null) return;

        float tendency = playerStats.EvolutionTendency;
        float factor = playerStats.EvolveFollowerBuffFactor;
        float mult = Mathf.Max(0f, 1f + (-tendency) * factor);

        _core.Health.MaxHealth = Mathf.Max(_origMaxHealth * mult * MaxHealthMultiplier, 1f);
        _core.Health.PatrolSpeed = _origPatrolSpeed * mult;
        _core.Health.ChaseSpeed = _origChaseSpeed * mult;
        _core.Health.DetectionRange = _origDetectionRange * mult;
        _core.Health.AttackRange = _origAttackRange * mult;
        _core.Health.ContactDamage = _origContactDamage * mult * DamageMultiplier;
        _core.Health.ContactDamageCooldown = _origContactDamageCooldown * mult;

        // 应用随从技能冷却乘区
        if (_skillManager != null)
        {
            foreach (var s in _skillManager.SkillInstances)
                s.CooldownFactor = FollowerCooldownFactor;
        }
    }

    /// <summary>刷新所有活跃随从的进化倾向 buff（由 PlayerStats 在倾向值变化时调用）</summary>
    public static void RefreshAllFollowers(float tendency, float factor)
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    /// <summary>刷新所有活跃随从（道具增强变化时调用）</summary>
    public static void RefreshAllFollowers()
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    private void Update()
    {
        if (!_isActive || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        Vector2 pos = transform.position;
        Vector2 playerPos = _player.position;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = (pos - playerPos).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(playerPos);
            return;
        }

        // 寻找最近的敌人
        Transform nearestEnemy = FindNearestEnemy(pos);

        if (nearestEnemy != null)
        {
            Vector2 enemyPos = nearestEnemy.position;
            float distToEnemy = Vector2.Distance(pos, enemyPos);

            if (distToEnemy <= _attackRange)
            {
                _movement?.Stop();

                // 尝试释放技能
                if (_skillManager != null && _skillManager.SkillInstances.Count > 0)
                {
                    Vector2 dir = (enemyPos - pos).normalized;
                    _skillManager.TryCastSkill(0, _core, dir);
                }
            }
            else
            {
                _movement?.MoveTowardsPosition(enemyPos, _followSpeed);
            }
            return;
        }

        // 没有敌人 → 跟随玩家
        float distToPlayer = Vector2.Distance(pos, playerPos);
        if (distToPlayer > _followDistance)
        {
            _movement?.MoveTowardsPosition(playerPos, _followSpeed);
        }
        else
        {
            _movement?.Stop();
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        // 随从传送由 MapManager.TeleportFollowers 统一处理（在玩家传送到新房间之后）
    }

    private void HandleDeath()
    {
        _isActive = false;
        _isReviving = true;

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();

        // 隐藏视觉
        foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            sr.enabled = false;

        StartCoroutine(RespawnRoutine());
    }

    private IEnumerator RespawnRoutine()
    {
        yield return new WaitForSeconds(_respawnDelay);

        // 复活
        if (_core?.Health != null)
        {
            _core.Health.Revive();
            ApplyEvolutionBuff();
        }

        // 传送到玩家身边
        if (_player != null)
            _movement?.Teleport(_player.position);

        // 恢复视觉和碰撞
        foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            sr.enabled = true;
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = true;

        _isActive = true;
        _isReviving = false;
    }

    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        if (scene.name == "Start" || scene.name == "Result" || scene.name == "Winning")
        {
            Destroy(gameObject);
            return;
        }

        // 游戏场景：重新查找玩家引用
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            _player = PlayerManager.Instance.CurrentPlayer.transform;
        else
            _player = GameObject.FindGameObjectWithTag("Player")?.transform;

        // 传送到玩家身边（防止随从出现在旧位置）
        if (_player != null && _movement != null && !_isReviving)
            _movement.Teleport(_player.position);
    }
}

using System;
using UnityEngine;

/// <summary>
/// 敌人统计数据组件 — 所有属性的唯一数据源（类似 PlayerStats）。
/// 血量、移速、感知范围、攻击范围、碰撞伤害等统一在此管理，
/// 提供 GetStatValue / SetStatValue 接口供 Buff 系统读写。
///
/// 数据初始化：EnemyCore 在 Awake 中从 EnemyConfig 赋值，然后调用 Initialize()。
/// </summary>
public class EnemyStats : MonoBehaviour, IDamageable, IHealable
{
    // ════════════════════════════════════════════
    //  生命
    // ════════════════════════════════════════════
    [Header("──── 生命 ────")]
    public float MaxHealth = 30f;
    private float _health;
    private bool _isDead = false;
    private bool _initialized = false;

    // ════════════════════════════════════════════
    //  移动速度
    // ════════════════════════════════════════════
    [Header("──── 移动速度 ────")]
    [Tooltip("巡逻速度")]
    public float PatrolSpeed = 1f;
    [Tooltip("追击速度")]
    public float ChaseSpeed = 2.5f;

    // ════════════════════════════════════════════
    //  感知与攻击
    // ════════════════════════════════════════════
    [Header("──── 感知与攻击 ────")]
    [Tooltip("发现玩家范围")]
    public float DetectionRange = 5f;
    [Tooltip("攻击范围")]
    public float AttackRange = 1.2f;

    // ════════════════════════════════════════════
    //  碰撞伤害
    // ════════════════════════════════════════════
    [Header("──── 碰撞伤害 ────")]
    [Tooltip("接触玩家时造成的伤害")]
    public float ContactDamage = 10f;
    [Tooltip("碰撞伤害冷却（秒）")]
    public float ContactDamageCooldown = 1f;

    // ──────────────────────────────────────────
    //  只读属性
    // ──────────────────────────────────────────
    public bool IsDead => _isDead;
    public float CurrentHealth => _health;

    // ──────────────────────────────────────────
    //  事件
    // ──────────────────────────────────────────
    public event Action<float, float> OnHealthChanged;
    public event Action OnDied;
    public event Action<float> OnDamaged;
    /// <summary>属性变化事件：参数为 (属性名)</summary>
    public event Action<string> OnStatChanged;

    /// <summary>技能命中附带目标当前生命的百分比伤害（蛋白激酶），0=关闭</summary>
    public static float OnSkillHitPercentDamage = 0f;

    // ──────────────────────────────────────────
    //  初始化
    // ──────────────────────────────────────────

    /// <summary>
    /// 由 EnemyCore 在设置各项属性后调用。
    /// 确保 _health 从最终 MaxHealth 初始化。
    /// </summary>
    public void Initialize()
    {
        if (_initialized) return;
        _health = MaxHealth;
        _initialized = true;
    }

    // ──────────────────────────────────────────
    //  IDamageable
    // ──────────────────────────────────────────

    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        var immunity = GetComponent<DamageImmunity>();
        if (immunity != null && immunity.IsImmune) return;

        // 受击闪避（肌纤维应激细胞等）：成功闪避则免疫本次伤害并滑移
        var dodge = GetComponent<DodgeComponent>();
        if (dodge != null)
        {
            // 闪避方向：远离最近的敌人（通常是玩家/攻击者方向的反向）
            Vector2 hitDir = Vector2.right;
            var player = PlayerManager.Instance != null ? PlayerManager.Instance.CurrentPlayer : null;
            if (player != null)
                hitDir = ((Vector2)transform.position - (Vector2)player.transform.position).normalized;
            if (hitDir.sqrMagnitude < 0.01f)
                hitDir = Vector2.right;

            if (dodge.TryDodge(hitDir))
                return;  // 闪避成功，免疫本次伤害
        }

        // 伤害吸收护盾（角质增厚细胞等）：先免伤再吸收
        var absorbShield = GetComponent<AbsorbShield>();
        if (absorbShield != null && absorbShield.IsActive)
            absorbShield.TryAbsorb(ref damage);

        if (damage <= 0f) return;

        var analgesic = GetComponent<AnalgesicBlockRuntime>();
        if (analgesic != null && analgesic.IsActive)
            damage = analgesic.SplitDamage(damage);

        // 蛋白激酶：技能命中附带目标当前生命百分比伤害
        if (SkillInstance.SkillDamageActive && OnSkillHitPercentDamage > 0f)
            damage += _health * OnSkillHitPercentDamage;

        _health -= damage;
        _health = Mathf.Max(_health, 0f);

        DamagePopup.Spawn(transform.position, damage);

        if (CameraShake.Instance != null)
            CameraShake.Instance.Shake(0.7f);

        OnDamaged?.Invoke(damage);
        OnHealthChanged?.Invoke(_health, MaxHealth);

        if (_health <= 0f)
            Die();
    }

    // ──────────────────────────────────────────
    //  IHealable
    // ──────────────────────────────────────────

    public void Heal(float amount)
    {
        if (_isDead) return;
        _health = Mathf.Min(_health + amount, MaxHealth);
        OnHealthChanged?.Invoke(_health, MaxHealth);
    }

    private void Die()
    {
        if (_isDead) return;
        _isDead = true;
        OnDied?.Invoke();
    }

    /// <summary>清除 OnDied 事件的所有订阅者（同化时切换死亡处理）。</summary>
    public void ClearOnDied()
    {
        OnDied = null;
    }

    /// <summary>复活：重置死亡状态并回满血。</summary>
    public void Revive()
    {
        _isDead = false;
        _health = MaxHealth;
        OnHealthChanged?.Invoke(_health, MaxHealth);
    }

    // ──────────────────────────────────────────
    //  Buff 系统属性读写接口（类同 PlayerStats）
    // ──────────────────────────────────────────

    public float GetStatValue(string statName)
    {
        return statName switch
        {
            "MaxHealth"             => MaxHealth,
            "Health"                => _health,
            "PatrolSpeed"           => PatrolSpeed,
            "ChaseSpeed"            => ChaseSpeed,
            "DetectionRange"        => DetectionRange,
            "AttackRange"           => AttackRange,
            "ContactDamage"         => ContactDamage,
            "ContactDamageCooldown" => ContactDamageCooldown,
            _ => throw new ArgumentException($"EnemyStats: 未知属性名 '{statName}'")
        };
    }

    public void SetStatValue(string statName, float value)
    {
        switch (statName)
        {
            case "MaxHealth":
                MaxHealth = Mathf.Max(value, 1f);
                _health = Mathf.Min(_health, MaxHealth);
                break;
            case "Health":
                _health = Mathf.Clamp(value, 0f, MaxHealth);
                break;
            case "PatrolSpeed":
                PatrolSpeed = Mathf.Max(value, 0f);
                break;
            case "ChaseSpeed":
                ChaseSpeed = Mathf.Max(value, 0f);
                break;
            case "DetectionRange":
                DetectionRange = Mathf.Max(value, 0f);
                break;
            case "AttackRange":
                AttackRange = Mathf.Max(value, 0f);
                break;
            case "ContactDamage":
                ContactDamage = Mathf.Max(value, 0f);
                break;
            case "ContactDamageCooldown":
                ContactDamageCooldown = Mathf.Max(value, 0f);
                break;
            default:
                throw new ArgumentException($"EnemyStats: 未知属性名 '{statName}'");
        }
        OnStatChanged?.Invoke(statName);
    }
}

using System;
using UnityEngine;

public class Projectile : MonoBehaviour
{
    public enum OwnerType { Player, Enemy }

    /// <summary>全局投射物命中事件 (projectile, hitTarget)</summary>
    public static event Action<Projectile, GameObject> OnAnyProjectileHit;

    /// <summary>灵体子弹模式：玩家方投射物穿透障碍物</summary>
    public static bool SpiritBulletMode;

    /// <summary>跟踪模式：玩家方投射物追踪最近敌人</summary>
    public static bool HomingMode;

    /// <summary>全局弹幕速度倍率（道具效果），1=正常，0.5=半速</summary>
    public static float GlobalSpeedMultiplier = 1f;

    /// <summary>玩家方子弹大小倍率（道具效果），1=正常</summary>
    public static float BulletScaleMultiplier = 1f;

    // === 距离衰减模式（甲亢道具） ===
    /// <summary>距离衰减模式：玩家方子弹伤害和大小随飞行距离衰减</summary>
    public static bool DistanceDamageMode;
    public static float DistanceDamageMaxMult = 3f;
    public static float DistanceDamageMinMult = 0.1f;
    public static float DistanceScaleMaxMult = 1.5f;
    public static float DistanceScaleMinMult = 0.3f;
    public static float DistanceMaxRange = 8f;

    [Header("子弹参数")]
    [SerializeField] private float speed = 8f;
    [SerializeField] private float damage = 10f;
    [SerializeField] private float lifeTime = 3f;

    /// <summary>投射物所属主人GameObject</summary>
    public GameObject Caster { get; private set; }

    /// <summary>投射物阵营（公开只读，供地面区域等组件读取）</summary>
    public OwnerType Owner => _owner;

    private Vector2 _direction;
    private OwnerType _owner;
    private bool _isInitialized;
    private Vector3 _spawnPos;

    /// <summary>是否被时停冻结</summary>
    public bool IsFrozen { get; private set; }
    private float _frozenLifetimeRemain;

    /// <param name="caster">投射物所有者GameObject，可选</param>
    public void Initialize(Vector2 dir, float spd, float dmg, OwnerType owner, GameObject caster = null)
    {
        _direction = dir.normalized;
        speed = spd;
        damage = dmg;
        _owner = owner;
        Caster = caster ?? gameObject;
        _isInitialized = true;
        IsFrozen = false;
        _spawnPos = transform.position;

        // 用 Invoke 延时回收（替代 Destroy(gameObject, lifeTime)）
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), lifeTime);
    }

    /// <summary>冻结投射物（停止移动+暂停生命周期）</summary>
    public void Freeze()
    {
        if (!_isInitialized || IsFrozen) return;
        IsFrozen = true;
        // 记录剩余生命时间并取消自动回收
        _frozenLifetimeRemain = Mathf.Max(lifeTime * 0.5f, 1f);
        CancelInvoke(nameof(ReturnToPool));
    }

    /// <summary>解冻投射物，恢复移动和生命周期</summary>
    public void Unfreeze()
    {
        if (!_isInitialized || !IsFrozen) return;
        IsFrozen = false;
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), _frozenLifetimeRemain);
    }

    /// <summary>重置状态（池化复用时由 ProjectilePool 间接调用）</summary>
    public void ResetState()
    {
        _isInitialized = false;
        _direction = Vector2.zero;
        Caster = null;
        transform.localScale = Vector3.one;
        CancelInvoke(nameof(ReturnToPool));
    }

    void Update()
    {
        if (!_isInitialized || IsFrozen) return;

        // 跟踪模式：玩家方子弹追踪最近敌人
        if (HomingMode && _owner == OwnerType.Player)
        {
            Transform nearest = FindNearestEnemy(transform.position);
            if (nearest != null)
            {
                Vector2 toTarget = (nearest.position - transform.position).normalized;
                _direction = Vector2.Lerp(_direction, toTarget, 8f * Time.deltaTime).normalized;
            }
        }

        // 玩家方子弹不受全局减速影响
        float mult = _owner == OwnerType.Player ? 1f : GlobalSpeedMultiplier;
        transform.Translate(_direction * speed * mult * Time.deltaTime, Space.World);

        // 玩家方子弹大小：距离衰减或固定倍率
        if (_owner == OwnerType.Player)
        {
            if (DistanceDamageMode)
            {
                float dist = Vector3.Distance(transform.position, _spawnPos);
                float t = Mathf.Clamp01(dist / DistanceMaxRange);
                float scaleMult = Mathf.Lerp(DistanceScaleMaxMult, DistanceScaleMinMult, t);
                transform.localScale = Vector3.one * scaleMult * BulletScaleMultiplier;
            }
            else if (BulletScaleMultiplier != 1f)
            {
                transform.localScale = Vector3.one * BulletScaleMultiplier;
            }
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, 4f, ~0);
        Transform nearest = null;
        float minDist = float.MaxValue;
        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist) { minDist = d; nearest = hit.transform; }
        }
        return nearest;
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_isInitialized) return;

        if (other.CompareTag("Obstacles"))
        {
            if (!SpiritBulletMode || _owner != OwnerType.Player)
                ReturnToPool();
            return;
        }

        string targetTag = _owner == OwnerType.Player ? "Enemy" : "Player";

        // 动情腺溢散（互相攻击）：敌人投射物命中其他敌人时，若目标带混淆 debuff 则也造成伤害
        bool confusionHit = false;
        if (_owner == OwnerType.Enemy && other.CompareTag("Enemy"))
        {
            var buffMgr = other.GetComponent<BuffManager>();
            confusionHit = buffMgr != null && buffMgr.HasBuff("gland_confusion");
        }

        if (!other.CompareTag(targetTag) && !confusionHit) return;

        // 护盾拦截：目标架盾中则挡住弹幕（不造成伤害）
        var shield = other.GetComponent<KeratinShieldRuntime>();
        if (shield != null && shield.IsActive)
        {
            shield.TryBlock();
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
            ReturnToPool();
            return;
        }

        // 因子掠夺：命中目标后先偷取其增益 buff（目标存活时才有 buff 可偷）
        var plunder = GetComponent<BuffPlunderOnHit>();
        if (plunder != null)
            plunder.TryPlunder(other.gameObject);

        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            float finalDamage = damage;

            // 距离衰减模式：根据飞行距离计算实际伤害
            if (DistanceDamageMode && _owner == OwnerType.Player)
            {
                float dist = Vector3.Distance(transform.position, _spawnPos);
                float t = Mathf.Clamp01(dist / DistanceMaxRange);
                float mult = Mathf.Lerp(DistanceDamageMaxMult, DistanceDamageMinMult, t);
                finalDamage = damage * mult;
            }

            damageable.TakeDamage(finalDamage);
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
        }

        ReturnToPool();
    }

    private void OnBecameInvisible()
    {
        ReturnToPool();
    }

    private void ReturnToPool()
    {
        if (!_isInitialized) return;
        ResetState();
        ProjectilePool.Return(gameObject);
    }
}

using UnityEngine;

/// <summary>
/// 抽象状态基类。每个具体状态应继承该类并实现 Enter/Update/Exit。
/// 状态持有对 EnemyCore 的引用以便控制敌人行为。
/// </summary>
public abstract class EnemyStateBase
{
    protected EnemyCore Core { get; private set; }

    public EnemyStateBase(EnemyCore core)
    {
        Core = core;
    }

    /// <summary>进入状态时调用一次</summary>
    public virtual void Enter() { }

    /// <summary>每帧由状态机调用</summary>
    public virtual void Tick() { }

    /// <summary>退出状态时调用一次</summary>
    public virtual void Exit() { }
}

using UnityEngine;

/// <summary>
/// 追击状态：高速追向玩家。
/// 脱战距离 = 3× detectionRange，短暂失去视线切 SearchState。
/// 进入攻击范围 → AttackState。
/// </summary>
public class ChaseState : EnemyStateBase
{
    public ChaseState(EnemyCore core) : base(core) { }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.Health == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 playerPos = Core.PlayerTarget.position;
        float sqrDist = ((Vector2)Core.transform.position - playerPos).sqrMagnitude;
        float attackSqr = Core.Health.AttackRange * Core.Health.AttackRange;

        // 脱战判定：3× detectionRange
        float leashRange = Core.Health.DetectionRange * 3f;
        if (sqrDist > leashRange * leashRange)
        {
            Core.Movement?.Stop();
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        // 视线检测
        bool canSee = Core.Movement.HasLineOfSight(playerPos, Core.Health.DetectionRange);
        if (!canSee)
        {
            Core.StateMachine.ChangeState(new SearchState(Core));
            return;
        }

        Core.LastKnownPlayerPosition = playerPos;

        // 轴向喷射型敌人（结核分枝杆菌）：进入攻击范围即进入喷射状态（沿三个固定角发射），而非继续追击
        if (Core.config != null && Core.config.useAxialSpray)
        {
            if (sqrDist <= attackSqr)
            {
                Core.StateMachine.ChangeState(new AxialSprayState(Core));
                return;
            }
        }

        // 进入攻击范围
        if (sqrDist <= attackSqr)
        {
            Core.StateMachine.ChangeState(new AttackState(Core));
            return;
        }

        // 追击
        Core.Movement?.MoveTowardsPosition(playerPos, Core.Health.ChaseSpeed);
    }
}

using UnityEngine;

/// <summary>
/// 攻击状态：停止移动，用技能攻击玩家。
/// 玩家离开攻击范围 → ChaseState。
/// </summary>
public class AttackState : EnemyStateBase
{
    public AttackState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        Core.Movement?.Stop();
    }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.Health == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 playerPos = Core.PlayerTarget.position;
        float sqrDist = ((Vector2)Core.transform.position - playerPos).sqrMagnitude;
        float attackSqr = Core.Health.AttackRange * Core.Health.AttackRange;

        // 玩家离开攻击范围 → 追击
        if (sqrDist > attackSqr * 1.2f)
        {
            Core.StateMachine.ChangeState(new ChaseState(Core));
            return;
        }

        // 保持靠近
        Core.Movement?.MoveTowardsPosition(playerPos, Core.Health.ChaseSpeed, 0.3f);

        // 释放技能：支持随机选择就绪技能（多技能敌人概率发动）
        if (Core.SkillManager != null && Core.SkillManager.SkillInstances.Count > 0)
        {
            if (Core.config != null && Core.config.useRandomSkill)
                Core.SkillManager.TryCastRandomReadySkill(Core, Core.GetTargetDirection());
            else
                Core.SkillManager.TryCastSkill(0, Core, Core.GetTargetDirection());
        }
    }
}

using UnityEngine;

/// <summary>
/// 空闲状态：原地待命，定期检测玩家。
/// 发现玩家 → ChaseState；有 patrolPoints → PatrolState。
/// </summary>
public class IdleState : EnemyStateBase
{
    public IdleState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        Core.Movement?.Stop();
    }

    public override void Tick()
    {
        if (Core.PlayerTarget == null)
        {
            TryFindPlayer();
            return;
        }
        if (Core.Health == null) return;

        Vector2 playerPos = Core.PlayerTarget.position;
        bool canSee = Core.Movement.HasLineOfSight(playerPos, Core.Health.DetectionRange);

        if (canSee)
        {
            Core.LastKnownPlayerPosition = playerPos;
            Core.StateMachine.ChangeState(new ChaseState(Core));
            return;
        }

        var pts = Core.config != null ? Core.config.patrolPoints : null;
        if (pts != null && pts.Count > 0)
            Core.StateMachine.ChangeState(new PatrolState(Core));
    }

    private void TryFindPlayer()
    {
        var p = GameObject.FindGameObjectWithTag("Player");
        if (p != null) Core.PlayerTarget = p.transform;
    }
}

using UnityEngine;

/// <summary>
/// 巡逻状态：沿 patrolPoints 逐个移动，到达后短暂停留。
/// 发现玩家 → ChaseState。
/// </summary>
public class PatrolState : EnemyStateBase
{
    private int _currentIndex;
    private float _waitTimer;
    private static readonly float WaitPerPoint = 0.8f;
    private static readonly float ArriveThreshold = 0.3f;

    public PatrolState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _currentIndex = 0;
        _waitTimer   = 0f;
    }

    public override void Tick()
    {
        if (Core.PlayerTarget != null && Core.Health != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.Health.DetectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        var pts = Core.config != null ? Core.config.patrolPoints : null;
        if (pts == null || pts.Count == 0)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 target = pts[_currentIndex];
        float sqrDist = ((Vector2)Core.transform.position - target).sqrMagnitude;

        if (sqrDist < ArriveThreshold * ArriveThreshold)
        {
            Core.Movement?.Stop();
            _waitTimer += Time.deltaTime;
            if (_waitTimer >= WaitPerPoint)
            {
                _waitTimer = 0f;
                _currentIndex = (_currentIndex + 1) % pts.Count;
            }
        }
        else
        {
            _waitTimer = 0f;
            Core.Movement?.MoveTowardsPosition(target, Core.Health.PatrolSpeed);
        }
    }
}

using UnityEngine;

/// <summary>
/// 搜索状态：移动到玩家最后已知位置，到达后等待 searchDuration 秒。
/// 重新发现玩家 → ChaseState；超时 → IdleState。
/// </summary>
public class SearchState : EnemyStateBase
{
    private float _enterTime;
    private float _searchDuration = 2.5f;
    private bool _arrived;
    private static readonly float ArriveThreshold = 0.4f;

    public SearchState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _enterTime = Time.time;
        _arrived   = false;
    }

    public override void Tick()
    {
        // 期间重新发现玩家 → 立即追击
        if (Core.PlayerTarget != null && Core.Health != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.Health.DetectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        Vector2 lastPos = Core.LastKnownPlayerPosition;
        float sqrDist = ((Vector2)Core.transform.position - lastPos).sqrMagnitude;

        if (!_arrived)
        {
            if (sqrDist < ArriveThreshold * ArriveThreshold)
            {
                _arrived   = true;
                _enterTime = Time.time;
                Core.Movement?.Stop();
            }
            else
            {
                // 搜索时用 patrolSpeed，额外减速 0.8
                Core.Movement?.MoveTowardsPosition(lastPos,
                    Core.Health != null ? Core.Health.PatrolSpeed : 1f, 0.8f);
            }
        }
        else
        {
            Core.Movement?.Stop();
            if (Time.time - _enterTime > _searchDuration)
            {
                Core.StateMachine.ChangeState(new IdleState(Core));
            }
        }
    }
}

using UnityEngine;

/// <summary>
/// 混乱状态：敌人随处乱走（随机方向漫步），不检测玩家、不攻击、不施放技能。
/// 由急性谵妄 debuff 施加。
/// </summary>
public class ConfusedState : EnemyStateBase
{
    private Vector2 _wanderDir;
    private float _changeTimer;
    private static readonly float ChangeInterval = 0.8f;
    private static readonly float WanderDistance = 3f;

    public ConfusedState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _changeTimer = 0f;
        _wanderDir = Random.insideUnitCircle.normalized;
    }

    public override void Tick()
    {
        _changeTimer += Time.deltaTime;
        if (_changeTimer >= ChangeInterval)
        {
            _changeTimer = 0f;
            _wanderDir = Random.insideUnitCircle.normalized;
        }

        Vector2 target = (Vector2)Core.transform.position + _wanderDir * WanderDistance;
        float speed = Core.Health != null ? Core.Health.PatrolSpeed : 1f;
        Core.Movement?.MoveTowardsPosition(target, speed);
    }
}

using UnityEngine;

/// <summary>
/// 死亡状态：停止移动、禁用碰撞，延迟销毁 GameObject。
/// </summary>
public class DeadState : EnemyStateBase
{
    private float _destroyDelay = 0.5f;
    private float _deadTime;

    public DeadState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _deadTime = Time.time;

        Core.Movement?.Stop();

        // 禁用所有 Collider2D 防止死亡后继续触发碰撞
        foreach (var col in Core.GetComponentsInChildren<Collider2D>())
        {
            col.enabled = false;
        }
    }

    public override void Tick()
    {
        if (Time.time - _deadTime >= _destroyDelay)
        {
            Object.Destroy(Core.gameObject);
        }
    }
}

